<?php declare(strict_types=1);require __DIR__.'/../includes/bootstrap.php';require_admin();$aid=(int)current_user()['user_id'];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf($_POST['csrf_token']??null);if(($_POST['action']??'')==='save')db()->prepare('INSERT INTO announcements(created_by_user_id,title,message,starts_at,ends_at,is_active) VALUES(?,?,?,?,?,TRUE)')->execute([$aid,trim($_POST['title']),trim($_POST['message']),$_POST['starts_at']?:null,$_POST['ends_at']?:null]);else db()->prepare('UPDATE announcements SET is_active=IF(is_active=1,0,1) WHERE announcement_id=?')->execute([(int)$_POST['announcement_id']]);flash('success','Announcement updated.');redirect('admin/announcements.php');}$rows=db()->query('SELECT * FROM announcements ORDER BY created_at DESC')->fetchAll();$pageTitle='Announcements';$activePage='announcements';require __DIR__.'/../includes/app_header.php';?><section class="page-head"><div><span class="eyebrow">SYSTEM MESSAGES</span><h1>Announcements</h1><p>Publish or disable system-wide messages.</p></div></section><div class="two-column"><section class="panel"><form class="form" method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><label>Title<input class="input" name="title" required></label><label>Message<textarea class="input" rows="4" name="message" required></textarea></label><div class="form-grid two"><label>Start<input class="input" type="datetime-local" name="starts_at"></label><label>End<input class="input" type="datetime-local" name="ends_at"></label></div><button class="btn btn-primary">Publish</button></form></section><section class="panel"><?php foreach($rows as$a):?><div class="saved-card"><div class="row-between"><strong><?=e($a['title'])?></strong><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="announcement_id" value="<?=$a['announcement_id']?>"><input type="hidden" name="action" value="toggle"><button class="text-button"><?=$a['is_active']?'Disable':'Enable'?></button></form></div><p><?=e($a['message'])?></p></div><?php endforeach;?></section></div><?php require __DIR__.'/../includes/footer.php';?>